result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "utf8.py", "content": """"UTF-8 codec implemented by hand, strict mode.

encode(codepoints) -> bytes
decode(data) -> list[int]

Strictness rules (mirroring the WHATWG/Unicode definition and CPython's
'utf-8' error='strict' behavior):
  * no overlong encodings (each code point must use its minimal form)
  * no surrogate code points U+D800..U+DFFF in either direction
  * no code points above U+10FFFF in either direction
  * no truncated sequences
  * no stray continuation bytes or other invalid lead bytes

All failures raise Utf8Error, which carries the byte offset of the
offending byte (for decode) or the index of the offending code point
(for encode).
"""

MAX_UNICODE = 0x10FFFF


class Utf8Error(ValueError):
    def __init__(self, message: str, offset: int):
        super().__init__(f"{message} at byte offset {offset}")
        self.offset = offset


def _encode_one(cp: int) -> bytes:
    if cp < 0:
        raise Utf8Error(f"negative code point U+{cp & 0xFFFFFFFFFFFF:X}", cp)
    if cp > MAX_UNICODE:
        raise Utf8Error(f"code point above U+10FFFF", MAX_UNICODE + 1)
    if 0xD800 <= cp <= 0xDFFF:
        raise Utf8Error(f"surrogate code point U+{cp:04X}", cp)

    if cp <= 0x7F:
        return bytes([cp])
    elif cp <= 0x7FF:
        return bytes([0xC0 | (cp >> 6), 0x80 | (cp & 0x3F)])
    elif cp <= 0xFFFF:
        return bytes([0xE0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)])
    else:
        return bytes([
            0xF0 | (cp >> 18),
            0x80 | ((cp >> 12) & 0x3F),
            0x80 | ((cp >> 6) & 0x3F),
            0x80 | (cp & 0x3F),
        ])


def encode(codepoints: list[int]) -> bytes:
    """Encode a list of Unicode code points as strict UTF-8."""
    return b"".join(_encode_one(cp) for cp in codepoints)


def decode(data: bytes) -> list[int]:
    """Decode strict UTF-8 bytes into a list of code points."""
    cps: list[int] = []
    i = 0
    n = len(data)

    while i < n:
        b0 = data[i]

        # ASCII fast path
        if b0 < 0x80:
            cps.append(b0)
            i += 1
            continue

        # Determine sequence length from the lead byte; reject anything
        # that is a continuation byte or outside the well-formed ranges.
        if 0xC2 <= b0 <= 0xDF:
            length, min_cp = 2, 0x80
        elif 0xE0 <= b0 <= 0xEF:
            length, min_cp = 3, 0x800
        elif 0xF0 <= b0 <= 0xF4:
            length, min_cp = 4, 0x10000
        elif 0x80 <= b0 <= 0xBF:
            raise Utf8Error("stray continuation byte", i)
        elif b0 == 0xC0 or b0 == 0xC1:
            raise Utf8Error("overlong encoding (C0/C1 lead byte)", i)
        elif 0xF5 <= b0 <= 0xFF:
            raise Utf8Error("invalid lead byte", i)
        else:  # pragma: no cover - unreachable given the branches above
            raise Utf8Error("invalid byte", i)

        if i + length > n:
            raise Utf8Error("truncated multi-byte sequence", i)

        # Continuation bytes must all be 10xxxxxx.
        for k in range(1, length):
            if data[i + k] & 0xC0 != 0x80:
                raise Utf8Error("expected continuation byte", i + k)

        cp = b0 & (0x7F >> (length - 1))
        for k in range(1, length):
            cp = (cp << 6) | (data[i + k] & 0x3F)

        if cp < min_cp:
            raise Utf8Error("overlong encoding", i)
        if 0xD800 <= cp <= 0xDFFF:
            raise Utf8Error("surrogate code point encoded", i)
        if cp > MAX_UNICODE:
            raise Utf8Error("code point above U+10FFFF", i)

        cps.append(cp)
        i += length

    return cps
